  5655  bool Flow::setDNSQuery(char *v) {
  5656    if ((v != NULL) && isDNS()) {
  5657      time_t last_pkt_rcvd = getInterface()->getTimeLastPktRcvd();
  5658
  5659      if (!protos.dns.last_query_shadow /* The first time the swap is done */
  5660          ||
  5661          protos.dns.last_query_update_time + 1 <
  5662          last_pkt_rcvd /* Latest swap occurred at least one second ago */) {
  5663        if (protos.dns.last_query_shadow) free(protos.dns.last_query_shadow);
  5664        protos.dns.last_query_shadow = protos.dns.last_query;
  5665        protos.dns.last_query = v; /* No need to strdup */
  5666        protos.dns.last_query_update_time = last_pkt_rcvd;
  5667
  5668        return true; /* Swap successful */
  5669      }
  5670    }
